// src/lib/send-email.ts
var appUrl = () => getAppUrl();
async function send(to, subject, html) {
  try {
    const config = getEmailConfig();
    if (!config)
      return;
    const recipients = Array.isArray(to) ? to.filter(Boolean) : [to].filter(Boolean);
    if (recipients.length === 0)
      return;
    await config.resend.emails.send({
      from: config.from,
      to: recipients,
      subject,
      html
    });
  } catch (err) {
    console.error("[email] Failed to send:", subject, err);
  }
}
async function sendNewMerchantAlert(params) {
  const t = templates.newMerchant({ ...params, app_url: params.app_url ?? appUrl() });
  await send(params.rep_email, t.subject, t.html);
}
async function sendLenderNotification(params) {
  const t = templates.lenderNotification({ ...params, app_url: params.app_url ?? appUrl() });
  await send(params.lender_email, t.subject, t.html);
}
async function sendOfferReceived(params) {
  const t = templates.offerReceived({ ...params, app_url: params.app_url ?? appUrl() });
  await send(params.recipient_email, t.subject, t.html);
}
async function sendOfferAccepted(params) {
  const t = templates.offerAccepted({ ...params, app_url: params.app_url ?? appUrl() });
  await send(params.recipient_email, t.subject, t.html);
}
async function sendStipulationRequested(params) {
  const t = templates.stipulationRequested({ ...params, app_url: params.app_url ?? appUrl() });
  await send(params.merchant_email, t.subject, t.html);
}
async function sendContractSent(params) {
  const t = templates.contractSent({ ...params, app_url: params.app_url ?? appUrl() });
  await send(params.merchant_email, t.subject, t.html);
}
async function sendDealFunded(params) {
  for (const recipient of params.recipients) {
    const t = templates.dealFunded({
      recipient_name: recipient.name,
      business_name: params.business_name,
      amount: params.amount,
      app_url: params.app_url ?? appUrl()
    });
    await send(recipient.email, t.subject, t.html);
  }
}

// src/lib/email-triggers.ts
async function getOffer(offerId) {
  const { data, error } = await supabaseAdmin.from("offers").select("id,merchant_id,lender_id,amount,factor_rate,term_months,payment_freq,status").eq("id", offerId).maybeSingle();
  if (error) {
    console.error("[email] Failed to fetch offer", offerId, error);
    return null;
  }
  return data ?? null;
}
function triggerNewMerchantAlert(merchantId) {
  (async () => {
    try {
      const merchant = await getMerchantEmailData(merchantId);
      if (!merchant?.assigned_rep_id)
        return;
      const rep = await getUserById(merchant.assigned_rep_id);
      if (!rep?.email)
        return;
      await sendNewMerchantAlert({
        rep_email: rep.email,
        rep_name: displayName(rep, "Sales Rep"),
        business_name: merchant.business_name,
        requested_amount: toNumber(merchant.requested_amount)
      });
    } catch (error) {
      console.error("[email] New merchant alert trigger failed", error);
    }
  })();
}
function triggerLenderNotifications(merchantId) {
  (async () => {
    try {
      const merchant = await getMerchantEmailData(merchantId);
      if (!merchant)
        return;
      const { data, error } = await supabaseAdmin.from("lender_matches").select("id,lender_id,lender:lenders(id,company_name,contact_name,contact_email)").eq("merchant_id", merchantId).returns();
      if (error) {
        console.error("[email] Failed to fetch lender matches", error);
        return;
      }
      for (const match of data ?? []) {
        const lender = match.lender;
        if (!lender?.contact_email)
          continue;
        await sendLenderNotification({
          lender_email: lender.contact_email,
          lender_name: lender.contact_name ?? lender.company_name,
          business_name: merchant.business_name,
          industry: merchant.industry ?? "N/A",
          state: merchant.state ?? "N/A",
          monthly_revenue: toNumber(merchant.monthly_revenue),
          requested_amount: toNumber(merchant.requested_amount),
          current_positions: merchant.current_positions ?? 0
        });
      }
    } catch (error) {
      console.error("[email] Lender notification trigger failed", error);
    }
  })();
}
function triggerOfferReceived(offerId) {
  (async () => {
    try {
      const offer = await getOffer(offerId);
      if (!offer)
        return;
      const merchant = await getMerchantEmailData(offer.merchant_id);
      const lender = await getLenderEmailData(offer.lender_id);
      if (!merchant || !lender)
        return;
      const merchantUser = await getUserById(merchant.user_id);
      const rep = await getUserById(merchant.assigned_rep_id);
      const common = {
        business_name: merchant.business_name,
        lender_name: lender.company_name,
        amount: toNumber(offer.amount),
        factor_rate: toNumber(offer.factor_rate),
        term_months: offer.term_months ?? 0,
        payment_freq: offer.payment_freq ?? "N/A"
      };
      if (merchantUser?.email) {
        await sendOfferReceived({
          recipient_email: merchantUser.email,
          recipient_name: displayName(merchantUser, "Merchant"),
          ...common
        });
      }
      if (rep?.email) {
        await sendOfferReceived({
          recipient_email: rep.email,
          recipient_name: displayName(rep, "Sales Rep"),
          ...common
        });
      }
    } catch (error) {
      console.error("[email] Offer received trigger failed", error);
    }
  })();
}
function triggerOfferAccepted(offerId) {
  (async () => {
    try {
      const offer = await getOffer(offerId);
      if (!offer)
        return;
      const merchant = await getMerchantEmailData(offer.merchant_id);
      const lender = await getLenderEmailData(offer.lender_id);
      if (!merchant || !lender)
        return;
      const rep = await getUserById(merchant.assigned_rep_id);
      const common = {
        business_name: merchant.business_name,
        amount: toNumber(offer.amount)
      };
      if (lender.contact_email) {
        await sendOfferAccepted({
          recipient_email: lender.contact_email,
          recipient_name: lender.contact_name ?? lender.company_name,
          ...common
        });
      }
      if (rep?.email) {
        await sendOfferAccepted({
          recipient_email: rep.email,
          recipient_name: displayName(rep, "Sales Rep"),
          ...common
        });
      }
    } catch (error) {
      console.error("[email] Offer accepted trigger failed", error);
    }
  })();
}
function triggerStipulationRequested(stipulationId) {
  (async () => {
    try {
      const { data: stipulation, error } = await supabaseAdmin.from("stipulations").select("id,merchant_id,lender_id,description").eq("id", stipulationId).maybeSingle();
      if (error) {
        console.error("[email] Failed to fetch stipulation", stipulationId, error);
        return;
      }
      if (!stipulation)
        return;
      const merchant = await getMerchantEmailData(stipulation.merchant_id);
      const lender = await getLenderEmailData(stipulation.lender_id);
      if (!merchant || !lender)
        return;
      const merchantUser = await getUserById(merchant.user_id);
      if (!merchantUser?.email)
        return;
      await sendStipulationRequested({
        merchant_email: merchantUser.email,
        merchant_name: displayName(merchantUser, "Merchant"),
        description: stipulation.description,
        lender_name: lender.company_name
      });
    } catch (error) {
      console.error("[email] Stipulation requested trigger failed", error);
    }
  })();
}
function triggerMerchantStatusEmail(merchantId, status) {
  (async () => {
    try {
      const merchant = await getMerchantEmailData(merchantId);
      if (!merchant)
        return;
      if (status === "contract sent") {
        const merchantUser = await getUserById(merchant.user_id);
        if (!merchantUser?.email)
          return;
        await sendContractSent({
          merchant_email: merchantUser.email,
          merchant_name: displayName(merchantUser, "Merchant"),
          business_name: merchant.business_name
        });
        return;
      }
      if (status === "FUNDED") {
        const merchantUser = await getUserById(merchant.user_id);
        const rep = await getUserById(merchant.assigned_rep_id);
        const admins = await getAdminUsers();
        const acceptedOffer = await getAcceptedOfferForMerchant(merchantId);
        const recipients = [merchantUser, rep, ...admins].filter((user) => Boolean(user?.email)).map((user) => ({ email: user.email, name: displayName(user) }));
        if (recipients.length === 0)
          return;
        await sendDealFunded({
          recipients,
          business_name: merchant.business_name,
          amount: toNumber(acceptedOffer?.amount)
        });
      }
    } catch (error) {
      console.error("[email] Merchant status trigger failed", error);
    }
  })();
}

// src/lib/session-auth.ts
var SESSION_COOKIE_NAME = "mca_session";
var SESSION_MAX_AGE_SECONDS = 60 * 60 * 24 * 7;
var isProduction = true;
function sessionCookieAttributes(maxAge) {
  return [
    "Path=/",
    `Max-Age=${maxAge}`,
    "HttpOnly",
    "SameSite=Lax",
    ...isProduction ? ["Secure"] : []
  ].join("; ");
}
function serializeSessionCookie(token) {
  return `${SESSION_COOKIE_NAME}=${encodeURIComponent(token)}; ${sessionCookieAttributes(SESSION_MAX_AGE_SECONDS)}`;
}
function serializeExpiredSessionCookie() {
  return `${SESSION_COOKIE_NAME}=; ${sessionCookieAttributes(0)}`;
}
function parseCookies(header) {
  const cookies = new Map;
  if (!header)
    return cookies;
  for (const part of header.split(";")) {
    const [rawName, ...rawValue] = part.trim().split("=");
    if (!rawName || rawValue.length === 0)
      continue;
    cookies.set(rawName, decodeURIComponent(rawValue.join("=")));
  }
  return cookies;
}
function getSessionToken(req) {
  return parseCookies(req.headers.get("cookie")).get(SESSION_COOKIE_NAME) ?? null;
}
function toAuthUser(row) {
  return {
    id: row.id,
    email: row.email,
    role: row.role,
    full_name: row.full_name,
    name: row.name
  };
}
async function findUserByEmail(email) {
  const { data, error } = await supabaseAdmin.from("users").select("id,email,role,full_name,name,is_disabled,disabled_at,closed_at,last_login_at,created_at").eq("email", email.toLowerCase()).maybeSingle();
  if (error)
    throw new Error(error.message);
  return data ?? null;
}
async function findCredentialAccount(email) {
  const user = await findUserByEmail(email);
  if (!user)
    return null;
  const { data, error } = await supabaseAdmin.from("account").select("password").eq("providerId", "credential").eq("userId", user.id).maybeSingle();
  if (error)
    throw new Error(error.message);
  return data ? { password: data.password, users: user } : null;
}
async function createUserWithCredential(params) {
  const now = new Date().toISOString();
  const userId = crypto.randomUUID();
  const { data: createdUser, error: userError } = await supabaseAdmin.from("users").insert({
    id: userId,
    email: params.email.toLowerCase(),
    password_hash: null,
    role: params.role,
    full_name: params.fullName,
    name: params.fullName,
    emailVerified: false,
    image: null,
    createdAt: now,
    updatedAt: now
  }).select("id,email,role,full_name,name,is_disabled,disabled_at,closed_at,last_login_at,created_at").single();
  if (userError)
    throw new Error(userError.message);
  const { error: accountError } = await supabaseAdmin.from("account").insert({
    id: crypto.randomUUID(),
    accountId: createdUser.id,
    providerId: "credential",
    userId: createdUser.id,
    password: params.passwordHash,
    createdAt: now,
    updatedAt: now
  });
  if (accountError) {
    await supabaseAdmin.from("users").delete().eq("id", createdUser.id);
    throw new Error(accountError.message);
  }
  return toAuthUser(createdUser);
}
async function createSession(userId) {
  const tokenBytes = new Uint8Array(32);
  crypto.getRandomValues(tokenBytes);
  const token = Array.from(tokenBytes, (byte) => byte.toString(16).padStart(2, "0")).join("");
  const now = new Date;
  const expiresAt = new Date(now.getTime() + SESSION_MAX_AGE_SECONDS * 1000).toISOString();
  const { error } = await supabaseAdmin.from("session").insert({
    id: crypto.randomUUID(),
    token,
    userId,
    expiresAt,
    createdAt: now.toISOString(),
    updatedAt: now.toISOString()
  });
  if (error)
    throw new Error(error.message);
  return token;
}
async function deleteSession(token) {
  const { error } = await supabaseAdmin.from("session").delete().eq("token", token);
  if (error)
    throw new Error(error.message);
}
async function getUserFromSessionToken(token) {
  if (!token)
    return null;
  const { data, error } = await supabaseAdmin.from("session").select("id,token,expiresAt, users:userId(id,email,role,full_name,name,is_disabled,disabled_at,closed_at,last_login_at,created_at)").eq("token", token).maybeSingle();
  if (error)
    throw new Error(error.message);
  if (!data?.users)
    return null;
  if (new Date(data.expiresAt).getTime() <= Date.now()) {
    await deleteSession(token);
    return null;
  }
  if (data.users.is_disabled || data.users.closed_at) {
    await deleteSession(token);
    return null;
  }
  return toAuthUser(data.users);
}

// src/lib/requireAuth.ts
async function requireAuth(req, role) {
  const user = await getUserFromSessionToken(getSessionToken(req));
  if (!user) {
    throw new Response("Unauthorized", { status: 401 });
  }
  if (role && user.role !== role) {
    throw new Response("Forbidden", { status: 403 });
  }
  return user;
}

// src/lib/route-utils.ts
function json(data, init) {
  return Response.json(data, init);
}
function badRequest(message = "Bad request") {
  return new Response(message, { status: 400 });
}
function forbidden(message = "Forbidden") {
  return new Response(message, { status: 403 });
}
function notFound(message = "Not found") {
  return new Response(message, { status: 404 });
}
function assertRole(user, roles) {
  return roles.includes(user.role) ? null : forbidden();
}
function getId(context) {
  return context?.params?.id ?? null;
}
async function readJson(req) {
  try {
    return await req.json();
  } catch {
    return {};
  }
}

// src/lib/list-query.ts
function getPagination(url) {
  const pageParam = Number.parseInt(url.searchParams.get("page") ?? "1", 10);
  const perPageParam = Number.parseInt(url.searchParams.get("per_page") ?? "50", 10);
  const page = Number.isFinite(pageParam) && pageParam > 0 ? pageParam : 1;
  const perPage = Number.isFinite(perPageParam) && perPageParam > 0 ? Math.min(100, perPageParam) : 50;
  const from = (page - 1) * perPage;
  const to = from + perPage - 1;
  return { page, perPage, from, to };
}
function cleanSearchTerm(value) {
  return (value ?? "").replace(/[%,()]/g, " ").trim();
}
function hasListParams(url) {
  return Array.from(url.searchParams.keys()).length > 0;
}
function paginatedJson(data, total, page, perPage) {
  return Response.json({ data, total: total ?? data.length, page, per_page: perPage });
}

// src/routes/merchants/index.ts
function sanitizeMerchantForLender(merchant, lenderId) {
  return {
    ...merchant,
    offers: (merchant.offers ?? []).filter((offer) => offer.lenderId === lenderId)
  };
}
async function GET(req) {
  const user = await requireAuth(req);
  const url = new URL(req.url);
  const shouldPaginate = hasListParams(url);
  const pagination = getPagination(url);
  const search = cleanSearchTerm(url.searchParams.get("search"));
  const status = url.searchParams.get("status");
  const repId = url.searchParams.get("rep_id");
  const state = url.searchParams.get("state");
  const industry = url.searchParams.get("industry");
  const minRevenue = url.searchParams.get("min_revenue");
  const maxRevenue = url.searchParams.get("max_revenue");
  const stale = url.searchParams.get("stale");
  let query = supabaseAdmin.from("merchants").select("*", { count: shouldPaginate ? "exact" : undefined });
  let currentLenderId = null;
  if (user.role === "sales_rep")
    query = query.eq("assigned_rep_id", user.id);
  if (user.role === "merchant")
    query = query.eq("user_id", user.id);
  if (user.role === "lender") {
    const { data: lender, error: lenderError } = await supabaseAdmin.from("lenders").select("id").eq("user_id", user.id).maybeSingle();
    if (lenderError)
      return badRequest(lenderError.message);
    if (!lender)
      return shouldPaginate ? paginatedJson([], 0, pagination.page, pagination.perPage) : json([]);
    currentLenderId = lender.id;
    const { data: matches, error: matchError } = await supabaseAdmin.from("lender_matches").select("merchant_id").eq("lender_id", lender.id).returns();
    if (matchError)
      return badRequest(matchError.message);
    const merchantIds = (matches ?? []).map((match) => match.merchant_id);
    if (merchantIds.length === 0)
      return shouldPaginate ? paginatedJson([], 0, pagination.page, pagination.perPage) : json([]);
    query = query.in("id", merchantIds);
  }
  if (search)
    query = query.or(`business_name.ilike.%${search}%,state.ilike.%${search}%,industry.ilike.%${search}%`);
  if (status)
    query = query.eq("status", status);
  if (repId && user.role === "admin")
    query = query.eq("assigned_rep_id", repId);
  if (state)
    query = query.eq("state", state);
  if (industry)
    query = query.ilike("industry", `%${industry}%`);
  if (minRevenue)
    query = query.gte("monthly_revenue", Number(minRevenue));
  if (maxRevenue)
    query = query.lte("monthly_revenue", Number(maxRevenue));
  if (stale === "true") {
    const threeDaysAgo = new Date(Date.now() - 3 * 24 * 60 * 60 * 1000).toISOString();
    query = query.lte("updated_at", threeDaysAgo);
  }
  query = query.order("created_at", { ascending: false });
  if (shouldPaginate)
    query = query.range(pagination.from, pagination.to);
  const { data, error, count } = await query.returns();
  if (error)
    return badRequest(error.message);
  const merchants = (data ?? []).map(rowToMerchant);
  const visibleMerchants = user.role === "lender" && currentLenderId ? merchants.map((merchant) => sanitizeMerchantForLender(merchant, currentLenderId)) : merchants;
  return shouldPaginate ? paginatedJson(visibleMerchants, count, pagination.page, pagination.perPage) : json(visibleMerchants);
}
async function POST(req) {
  const user = await requireAuth(req);
  const roleError = assertRole(user, ["admin", "sales_rep", "merchant"]);
  if (roleError)
    return roleError;
  const merchant = await req.json();
  const id = merchant.id || crypto.randomUUID();
  const newMerchant = { ...merchant, id };
  const insert = merchantToInsert(newMerchant, user.role === "merchant" ? user.id : undefined);
  const { data, error } = await supabaseAdmin.from("merchants").insert(insert).select("*").single();
  if (error)
    return badRequest(error.message);
  const created = rowToMerchant(data);
  const history = await supabaseAdmin.from("status_history").insert({
    merchant_id: created.id,
    changed_by: user.id,
    previous_status: null,
    new_status: created.status,
    note: "Merchant created"
  });
  if (history.error)
    return badRequest(history.error.message);
  triggerNewMerchantAlert(created.id);
  recordActivity({
    entity_type: "merchant",
    entity_id: created.id,
    user_id: user.id,
    activity_type: "system",
    body: `Merchant application created: ${data.business_name}`
  });
  return json(created, { status: 201 });
}

// src/lib/matching.ts
var toNumber2 = (value) => {
  if (value === null || value === undefined || value === "")
    return null;
  const parsed = typeof value === "number" ? value : Number(String(value).replace(/[^0-9.-]/g, ""));
  return Number.isFinite(parsed) ? parsed : null;
};
var normalizedList = (values) => (values ?? []).map((value) => value.trim().toLowerCase()).filter(Boolean);
function isMatch(merchant, lender) {
  const merchantRevenue = toNumber2(merchant.monthly_revenue);
  const lenderMinRevenue = toNumber2(lender.min_revenue);
  const lenderMaxRevenue = toNumber2(lender.max_revenue);
  if (lenderMinRevenue !== null && (merchantRevenue === null || merchantRevenue < lenderMinRevenue))
    return false;
  if (lenderMaxRevenue !== null && (merchantRevenue === null || merchantRevenue > lenderMaxRevenue))
    return false;
  if (lender.min_credit !== null && lender.min_credit !== undefined) {
    if (merchant.credit_score === null || merchant.credit_score === undefined || merchant.credit_score < lender.min_credit)
      return false;
  }
  if (lender.max_positions !== null && lender.max_positions !== undefined) {
    if (merchant.current_positions !== null && merchant.current_positions !== undefined && merchant.current_positions > lender.max_positions)
      return false;
  }
  const lenderIndustries = normalizedList(lender.industries);
  if (lenderIndustries.length > 0) {
    const merchantIndustry = merchant.industry?.trim().toLowerCase();
    if (!merchantIndustry || !lenderIndustries.includes(merchantIndustry))
      return false;
  }
  const lenderStates = normalizedList(lender.states);
  if (lenderStates.length > 0) {
    const merchantState = merchant.state?.trim().toLowerCase();
    if (!merchantState || !lenderStates.includes(merchantState))
      return false;
  }
  const requestedAmount = toNumber2(merchant.requested_amount);
  const lenderMinAmount = toNumber2(lender.min_amount);
  const lenderMaxAmount = toNumber2(lender.max_amount);
  if (lenderMinAmount !== null && (requestedAmount === null || requestedAmount < lenderMinAmount))
    return false;
  if (lenderMaxAmount !== null && (requestedAmount === null || requestedAmount > lenderMaxAmount))
    return false;
  return true;
}
async function runAutoMatch(merchantId, triggeredBy) {
  const { data: merchant, error: merchantError } = await supabaseAdmin.from("merchants").select("id,monthly_revenue,credit_score,current_positions,industry,state,requested_amount").eq("id", merchantId).single();
  if (merchantError)
    throw new Error(merchantError.message);
  const { data: lenders, error: lendersError } = await supabaseAdmin.from("lenders").select("id,min_revenue,max_revenue,min_credit,max_positions,industries,states,min_amount,max_amount,is_active").eq("is_active", true).returns();
  if (lendersError)
    throw new Error(lendersError.message);
  const matches = (lenders ?? []).filter((lender) => isMatch(merchant, lender)).map((lender) => ({
    merchant_id: merchantId,
    lender_id: lender.id,
    match_type: "auto",
    matched_by: null
  }));
  if (matches.length === 0)
    return [];
  const { error: upsertError } = await supabaseAdmin.from("lender_matches").upsert(matches, { onConflict: "merchant_id,lender_id", ignoreDuplicates: true });
  if (upsertError)
    throw new Error(upsertError.message);
  const { data: joined, error: joinedError } = await supabaseAdmin.from("lender_matches").select("*, lender:lenders(id,company_name,contact_name,contact_email)").eq("merchant_id", merchantId).in("lender_id", matches.map((match) => match.lender_id)).returns();
  if (joinedError)
    throw new Error(joinedError.message);
  return joined ?? [];
}

