async function fetchMerchant(id) {
  const { data, error } = await supabaseAdmin.from("merchants").select("*").eq("id", id).single();
  if (error)
    return error.code === "PGRST116" ? null : badRequest(error.message);
  return data;
}
async function getCurrentLenderId(userId) {
  const { data, error } = await supabaseAdmin.from("lenders").select("id").eq("user_id", userId).maybeSingle();
  if (error)
    return badRequest(error.message);
  return data?.id ?? null;
}
async function lenderCanReadMerchant(lenderId, merchantId) {
  const { data, error } = await supabaseAdmin.from("lender_matches").select("id").eq("lender_id", lenderId).eq("merchant_id", merchantId).maybeSingle();
  if (error)
    return badRequest(error.message);
  return Boolean(data);
}
function sanitizeMerchantForLender2(merchant, lenderId) {
  return {
    ...merchant,
    offers: (merchant.offers ?? []).filter((offer) => offer.lenderId === lenderId)
  };
}
function canRead(userRole, userId, row) {
  if (userRole === "admin")
    return true;
  if (userRole === "sales_rep")
    return row.assigned_rep_id === userId;
  if (userRole === "merchant")
    return row.user_id === userId;
  return false;
}
function recordRepAssignmentActivity(merchantId, assignedRepId, userId) {
  (async () => {
    let repName = assignedRepId ?? "Unassigned";
    if (assignedRepId) {
      const { data: rep } = await supabaseAdmin.from("users").select("full_name,name,email").eq("id", assignedRepId).maybeSingle();
      repName = rep?.full_name ?? rep?.name ?? rep?.email ?? assignedRepId;
    }
    recordActivity({
      entity_type: "merchant",
      entity_id: merchantId,
      user_id: userId,
      activity_type: "system",
      body: `Sales rep assigned: ${repName}`,
      metadata: { assigned_rep_id: assignedRepId }
    });
  })();
}
function sendRepAssignmentAlert(merchant) {
  if (!merchant.assigned_rep_id)
    return;
  (async () => {
    try {
      const { data: rep, error } = await supabaseAdmin.from("users").select("id,email,full_name,name,role").eq("id", merchant.assigned_rep_id).maybeSingle();
      if (error) {
        console.error("[email] Failed to fetch assigned rep", error);
        return;
      }
      if (!rep?.email)
        return;
      await sendNewMerchantAlert({
        rep_email: rep.email,
        rep_name: displayName(rep, "Sales Rep"),
        business_name: merchant.business_name,
        requested_amount: toNumber(merchant.requested_amount)
      });
    } catch (error) {
      console.error("[email] Rep assignment alert trigger failed", error);
    }
  })();
}
async function GET2(req, context) {
  const user = await requireAuth(req);
  const id = getId(context);
  if (!id)
    return badRequest();
  const row = await fetchMerchant(id);
  if (row instanceof Response)
    return row;
  if (!row)
    return notFound();
  if (user.role === "lender") {
    const lenderId = await getCurrentLenderId(user.id);
    if (lenderId instanceof Response)
      return lenderId;
    if (!lenderId)
      return forbidden();
    const canReadLenderMerchant = await lenderCanReadMerchant(lenderId, id);
    if (canReadLenderMerchant instanceof Response)
      return canReadLenderMerchant;
    if (!canReadLenderMerchant)
      return forbidden();
    return json(sanitizeMerchantForLender2(rowToMerchant(row), lenderId));
  }
  if (!canRead(user.role, user.id, row))
    return forbidden();
  return json(rowToMerchant(row));
}
async function PATCH(req, context) {
  const user = await requireAuth(req);
  const roleError = assertRole(user, ["admin", "sales_rep"]);
  if (roleError)
    return roleError;
  const id = getId(context);
  if (!id)
    return badRequest();
  const existing = await fetchMerchant(id);
  if (existing instanceof Response)
    return existing;
  if (!existing)
    return notFound();
  if (user.role === "sales_rep" && existing.assigned_rep_id !== user.id)
    return forbidden();
  const patch = await req.json();
  const hasAssignedRepId = Object.prototype.hasOwnProperty.call(patch, "assigned_rep_id");
  const hasSalesRepId = Object.prototype.hasOwnProperty.call(patch, "salesRepId");
  const nextAssignedRepId = hasAssignedRepId ? patch.assigned_rep_id ?? null : hasSalesRepId ? patch.salesRepId ?? null : existing.assigned_rep_id;
  const assignmentChanged = (hasAssignedRepId || hasSalesRepId) && nextAssignedRepId !== existing.assigned_rep_id;
  const currentPayload = rowToMerchant(existing);
  const merged = { ...currentPayload, ...patch, id };
  if (patch.businessInfo)
    merged.businessInfo = { ...currentPayload.businessInfo, ...patch.businessInfo };
  if (patch.owners)
    merged.owners = patch.owners;
  if (patch.agreements)
    merged.agreements = { ...currentPayload.agreements, ...patch.agreements };
  if (patch.documents)
    merged.documents = patch.documents;
  if (patch.offers)
    merged.offers = patch.offers;
  if (patch.matchedLenderIds)
    merged.matchedLenderIds = patch.matchedLenderIds;
  if (hasAssignedRepId || hasSalesRepId)
    merged.salesRepId = nextAssignedRepId ?? undefined;
  const update = merchantToUpdate(merged);
  if (hasAssignedRepId || hasSalesRepId)
    update.assigned_rep_id = nextAssignedRepId;
  const { data, error } = await supabaseAdmin.from("merchants").update(update).eq("id", id).select("*").single();
  if (error)
    return badRequest(error.message);
  if (assignmentChanged) {
    if (data.assigned_rep_id)
      sendRepAssignmentAlert(data);
    recordRepAssignmentActivity(id, data.assigned_rep_id, user.id);
  }
  if (patch.status && patch.status !== existing.status) {
    const history = await supabaseAdmin.from("status_history").insert({
      merchant_id: id,
      changed_by: user.id,
      previous_status: existing.status,
      new_status: patch.status
    });
    if (history.error)
      return badRequest(history.error.message);
    recordActivity({
      entity_type: "merchant",
      entity_id: id,
      user_id: user.id,
      activity_type: "status_change",
      body: `Status changed from "${existing.status}" to "${patch.status}"`,
      metadata: { previous_status: existing.status, new_status: patch.status }
    });
    if (patch.status === "sent to lender") {
      try {
        await runAutoMatch(id, user.id);
      } catch (matchError) {
        return badRequest(matchError instanceof Error ? matchError.message : "Could not run auto-match");
      }
    }
    if (patch.status === "contract sent" || patch.status === "FUNDED") {
      triggerMerchantStatusEmail(id, patch.status);
    }
  }
  return json(rowToMerchant(data));
}
async function DELETE(req, context) {
  const user = await requireAuth(req, "admin");
  const id = getId(context);
  if (!user || !id)
    return badRequest();
  const { error } = await supabaseAdmin.from("merchants").delete().eq("id", id);
  if (error)
    return badRequest(error.message);
  return new Response(null, { status: 204 });
}

