// src/routes/tasks/[id].ts
var PRIORITIES2 = ["low", "normal", "high", "urgent"];
var STATUSES = ["open", "completed", "cancelled"];
var isPriority2 = (value) => typeof value === "string" && PRIORITIES2.includes(value);
var isStatus = (value) => typeof value === "string" && STATUSES.includes(value);
function toTask(row) {
  return {
    id: row.id,
    assigned_to: row.assigned_to,
    created_by: row.created_by,
    entity_type: row.entity_type,
    entity_id: row.entity_id,
    title: row.title,
    description: row.description,
    priority: row.priority,
    status: row.status,
    due_at: row.due_at,
    completed_at: row.completed_at,
    created_at: row.created_at,
    updated_at: row.updated_at,
    assignee_name: row.assignee?.full_name ?? row.assignee?.name ?? row.assignee?.email
  };
}
async function fetchTask(id) {
  const { data, error } = await supabaseAdmin.from("tasks").select("*, assignee:assigned_to(full_name,name,email)").eq("id", id).maybeSingle();
  if (error)
    return badRequest(error.message);
  return data ?? null;
}
function canManageTask(userId, role, task) {
  if (role === "admin")
    return true;
  if (role === "sales_rep")
    return task.assigned_to === userId || task.created_by === userId;
  return false;
}
async function PATCH5(req, context) {
  const user = await requireAuth(req);
  const roleError = assertRole(user, ["admin", "sales_rep"]);
  if (roleError)
    return roleError;
  const id = getId(context);
  if (!id)
    return badRequest();
  const task = await fetchTask(id);
  if (task instanceof Response)
    return task;
  if (!task)
    return notFound();
  if (!canManageTask(user.id, user.role, task))
    return forbidden();
  const body = await req.json();
  if (body.status !== undefined && !isStatus(body.status))
    return badRequest("status is invalid");
  if (body.priority !== undefined && !isPriority2(body.priority))
    return badRequest("priority is invalid");
  const update = {
    updated_at: new Date().toISOString()
  };
  if (body.title !== undefined) {
    if (!body.title.trim())
      return badRequest("title cannot be empty");
    update.title = body.title.trim();
  }
  if (body.description !== undefined)
    update.description = body.description?.trim() || null;
  if (body.priority !== undefined)
    update.priority = body.priority;
  if (body.assigned_to !== undefined)
    update.assigned_to = body.assigned_to;
  if (body.due_at !== undefined)
    update.due_at = body.due_at;
  if (body.status !== undefined) {
    update.status = body.status;
    update.completed_at = body.status === "completed" ? new Date().toISOString() : null;
  }
  const { data, error } = await supabaseAdmin.from("tasks").update(update).eq("id", id).select("*, assignee:assigned_to(full_name,name,email)").single();
  if (error)
    return badRequest(error.message);
  const changedStatus = body.status && body.status !== task.status;
  recordActivity({
    entity_type: data.entity_type,
    entity_id: data.entity_id,
    user_id: user.id,
    activity_type: "task",
    body: changedStatus ? `Task ${data.status}: ${data.title}` : `Task updated: ${data.title}`,
    metadata: { task_id: data.id, status: data.status, previous_status: task.status }
  });
  return json(toTask(data));
}
async function DELETE6(req, context) {
  const user = await requireAuth(req);
  const roleError = assertRole(user, ["admin"]);
  if (roleError)
    return roleError;
  const id = getId(context);
  if (!id)
    return badRequest();
  const { error } = await supabaseAdmin.from("tasks").delete().eq("id", id);
  if (error)
    return badRequest(error.message);
  return new Response(null, { status: 204 });
}

// src/lib/renewals.ts
var RENEWAL_STATUSES = ["not_ready", "eligible", "contacted", "application_started", "submitted", "renewed", "declined", "not_interested"];
var PAYOFF_REQUEST_STATUSES = ["requested", "received", "expired", "used", "cancelled"];
function isRenewalStatus(value) {
  return typeof value === "string" && RENEWAL_STATUSES.includes(value);
}
function isPayoffRequestStatus(value) {
  return typeof value === "string" && PAYOFF_REQUEST_STATUSES.includes(value);
}
function defaultRenewalEligibilityDate(fundedAt) {
  const date = new Date(fundedAt);
  date.setDate(date.getDate() + 90);
  return date.toISOString().slice(0, 10);
}
function isRenewalEligible(eligibilityDate, status) {
  if (status === "renewed" || status === "declined" || status === "not_interested")
    return false;
  return new Date(`${eligibilityDate}T00:00:00Z`).getTime() <= Date.now();
}
function toRenewal(row) {
  return {
    id: row.id,
    merchant_id: row.merchant_id,
    funding_id: row.funding_id,
    eligibility_date: row.eligibility_date,
    status: row.status,
    estimated_balance: row.estimated_balance,
    payoff_amount: row.payoff_amount,
    assigned_rep_id: row.assigned_rep_id,
    last_contacted_at: row.last_contacted_at,
    next_follow_up_at: row.next_follow_up_at,
    notes: row.notes,
    created_by: row.created_by,
    created_at: row.created_at,
    updated_at: row.updated_at,
    merchant_name: row.merchant?.business_name,
    lender_name: row.funding?.lender?.company_name ?? null,
    funded_amount: row.funding?.funded_amount ?? null,
    funded_at: row.funding?.funded_at ?? null,
    assigned_rep_name: row.assigned_rep?.full_name ?? row.assigned_rep?.name ?? row.assigned_rep?.email ?? null,
    is_eligible: isRenewalEligible(row.eligibility_date, row.status)
  };
}
function toPayoffRequest(row) {
  return {
    id: row.id,
    merchant_id: row.merchant_id,
    funding_id: row.funding_id,
    renewal_id: row.renewal_id,
    requested_from_lender_id: row.requested_from_lender_id,
    requested_from_name: row.requested_from_name,
    payoff_amount: row.payoff_amount,
    requested_at: row.requested_at,
    received_at: row.received_at,
    expires_at: row.expires_at,
    file_document_id: row.file_document_id,
    status: row.status,
    notes: row.notes,
    created_by: row.created_by,
    created_at: row.created_at,
    updated_at: row.updated_at,
    merchant_name: row.merchant?.business_name,
    document_name: row.document?.file_name ?? null,
    funding_lender_id: row.funding?.lender_id ?? null
  };
}
async function ensureRenewalForFunding(params) {
  const eligibilityDate = defaultRenewalEligibilityDate(params.funded_at);
  const { data, error } = await supabaseAdmin.from("renewals").upsert({
    merchant_id: params.merchant_id,
    funding_id: params.funding_id,
    eligibility_date: eligibilityDate,
    status: "not_ready",
    assigned_rep_id: params.assigned_rep_id ?? null,
    created_by: params.created_by ?? null,
    updated_at: new Date().toISOString()
  }, { onConflict: "merchant_id,funding_id", ignoreDuplicates: true }).select("*, merchant:merchants(business_name,assigned_rep_id,user_id), funding:fundings(funded_amount,funded_at,lender:lenders(company_name)), assigned_rep:users!renewals_assigned_rep_id_fkey(full_name,name,email)").maybeSingle();
  if (error)
    throw new Error(error.message);
  return data ? toRenewal(data) : null;
}

// src/routes/fundings/index.ts
var FUNDED_STATUS = "FUNDED";
var PAYMENT_FREQUENCIES = ["daily", "weekly", "biweekly", "monthly"];
var FUNDING_TYPES = ["first_funding", "renewal", "additional_funding"];
function toNumber3(value) {
  if (value === null || value === undefined || value === "")
    return null;
  const parsed = Number(String(value).replace(/[^0-9.-]/g, ""));
  return Number.isFinite(parsed) ? parsed : null;
}
function toInt(value) {
  const parsed = toNumber3(value);
  return parsed === null ? null : Math.trunc(parsed);
}
function isPaymentFrequency(value) {
  return typeof value === "string" && PAYMENT_FREQUENCIES.includes(value);
}
function isFundingType(value) {
  return typeof value === "string" && FUNDING_TYPES.includes(value);
}
function toFunding(row) {
  return {
    id: row.id,
    merchant_id: row.merchant_id,
    lender_id: row.lender_id,
    offer_id: row.offer_id,
    funded_amount: row.funded_amount,
    payback_amount: row.payback_amount,
    factor_rate: row.factor_rate,
    buy_rate: row.buy_rate,
    sell_rate: row.sell_rate,
    payment_frequency: row.payment_frequency,
    term_days: row.term_days,
    funded_at: row.funded_at,
    funding_type: row.funding_type ?? "first_funding",
    renewal_number: row.renewal_number ?? 0,
    funding_position: row.funding_position ?? 1,
    created_by: row.created_by,
    notes: row.notes,
    created_at: row.created_at,
    updated_at: row.updated_at,
    merchant_name: row.merchant?.business_name,
    lender_name: row.lender?.company_name
  };
}
async function GET15(req) {
  const user = await requireAuth(req);
  if (user.role === "merchant" || user.role === "lender")
    return forbidden();
  const url = new URL(req.url);
  const shouldPaginate = hasListParams(url);
  const pagination = getPagination(url);
  const merchantId = url.searchParams.get("merchant_id");
  const from = url.searchParams.get("from");
  const to = url.searchParams.get("to");
  const lenderId = url.searchParams.get("lender_id");
  const repId = url.searchParams.get("rep_id");
  let query = supabaseAdmin.from("fundings").select("*, merchant:merchants(business_name,assigned_rep_id), lender:lenders(company_name)", { count: shouldPaginate ? "exact" : undefined });
  if (merchantId)
    query = query.eq("merchant_id", merchantId);
  if (from)
    query = query.gte("funded_at", from);
  if (to)
    query = query.lte("funded_at", to);
  if (lenderId)
    query = query.eq("lender_id", lenderId);
  if (user.role === "sales_rep") {
    const { data: merchants, error: error2 } = await supabaseAdmin.from("merchants").select("id").eq("assigned_rep_id", user.id).returns();
    if (error2)
      return badRequest(error2.message);
    const ids = (merchants ?? []).map((merchant) => merchant.id);
    if (ids.length === 0)
      return shouldPaginate ? paginatedJson([], 0, pagination.page, pagination.perPage) : json([]);
    query = query.in("merchant_id", ids);
  } else if (repId) {
    const { data: merchants, error: error2 } = await supabaseAdmin.from("merchants").select("id").eq("assigned_rep_id", repId).returns();
    if (error2)
      return badRequest(error2.message);
    const ids = (merchants ?? []).map((merchant) => merchant.id);
    if (ids.length === 0)
      return shouldPaginate ? paginatedJson([], 0, pagination.page, pagination.perPage) : json([]);
    query = query.in("merchant_id", ids);
  }
  query = query.order("funded_at", { ascending: false });
  if (shouldPaginate)
    query = query.range(pagination.from, pagination.to);
  const { data, error, count } = await query.returns();
  if (error)
    return badRequest(error.message);
  const fundings = (data ?? []).map(toFunding);
  return shouldPaginate ? paginatedJson(fundings, count, pagination.page, pagination.perPage) : json(fundings);
}
async function POST17(req) {
  const user = await requireAuth(req);
  const roleError = assertRole(user, ["admin", "sales_rep"]);
  if (roleError)
    return roleError;
  const body = await req.json();
  if (!body.merchant_id)
    return badRequest("merchant_id is required");
  const fundedAmount = toNumber3(body.funded_amount);
  if (fundedAmount === null || fundedAmount <= 0)
    return badRequest("funded_amount is required");
  if (body.payment_frequency && !isPaymentFrequency(body.payment_frequency))
    return badRequest("payment_frequency is invalid");
  const requestedFundingType = body.funding_type ?? undefined;
  if (requestedFundingType && !isFundingType(requestedFundingType))
    return badRequest("funding_type is invalid");
  const renewalNumber = toInt(body.renewal_number);
  const fundingPosition = toInt(body.funding_position);
  const { data: existingFundings, error: existingFundingsError } = await supabaseAdmin.from("fundings").select("id").eq("merchant_id", body.merchant_id).returns();
  if (existingFundingsError)
    return badRequest(existingFundingsError.message);
  const existingCount = existingFundings?.length ?? 0;
  const fundingType = requestedFundingType ?? (existingCount === 0 ? "first_funding" : "renewal");
  const finalRenewalNumber = fundingType === "renewal" ? renewalNumber && renewalNumber > 0 ? renewalNumber : Math.max(1, existingCount) : 0;
  const finalFundingPosition = fundingPosition && fundingPosition > 0 ? fundingPosition : existingCount + 1;
  const { data: merchantRow, error: merchantError } = await supabaseAdmin.from("merchants").select("*").eq("id", body.merchant_id).single();
  if (merchantError)
    return badRequest(merchantError.message);
  if (user.role === "sales_rep" && merchantRow.assigned_rep_id !== user.id)
    return forbidden();
  let lenderId = body.lender_id ?? null;
  let offerId = body.offer_id ?? null;
  let factorRate = toNumber3(body.factor_rate);
  if (offerId) {
    const { data: offer, error: offerError } = await supabaseAdmin.from("offers").select("*").eq("id", offerId).single();
    if (offerError)
      return badRequest(offerError.message);
    if (offer.merchant_id !== body.merchant_id)
      return badRequest("offer does not belong to merchant");
    lenderId = offer.lender_id;
    factorRate = factorRate ?? toNumber3(offer.factor_rate);
  }
  const { data: fundingRow, error: fundingError } = await supabaseAdmin.from("fundings").insert({
    merchant_id: body.merchant_id,
    lender_id: lenderId,
    offer_id: offerId,
    funded_amount: fundedAmount,
    payback_amount: toNumber3(body.payback_amount),
    factor_rate: factorRate,
    buy_rate: toNumber3(body.buy_rate),
    sell_rate: toNumber3(body.sell_rate),
    payment_frequency: body.payment_frequency ?? null,
    term_days: toInt(body.term_days),
    funded_at: body.funded_at || new Date().toISOString(),
    funding_type: fundingType,
    renewal_number: finalRenewalNumber,
    funding_position: finalFundingPosition,
    created_by: user.id,
    notes: body.notes?.trim() || null
  }).select("*, merchant:merchants(business_name,assigned_rep_id), lender:lenders(company_name)").single();
  if (fundingError)
    return badRequest(fundingError.message);
  const merchant = rowToMerchant(merchantRow);
  const updatedMerchant = { ...merchant, status: FUNDED_STATUS };
  const { error: merchantUpdateError } = await supabaseAdmin.from("merchants").update({ status: FUNDED_STATUS, payload: updatedMerchant, updated_at: new Date().toISOString() }).eq("id", body.merchant_id);
  if (merchantUpdateError)
    return badRequest(merchantUpdateError.message);
  if (merchantRow.status !== FUNDED_STATUS) {
    const { error: historyError } = await supabaseAdmin.from("status_history").insert({
      merchant_id: body.merchant_id,
      changed_by: user.id,
      previous_status: merchantRow.status,
      new_status: FUNDED_STATUS,
      note: "Deal marked funded"
    });
    if (historyError)
      return badRequest(historyError.message);
  }
  const brokerRevenueAmount = toNumber3(body.broker_revenue_amount);
  if (user.role === "admin" && brokerRevenueAmount !== null && brokerRevenueAmount >= 0) {
    const { error } = await supabaseAdmin.from("broker_revenue").insert({
      funding_id: fundingRow.id,
      merchant_id: body.merchant_id,
      lender_id: lenderId,
      revenue_type: "commission",
      basis_amount: fundedAmount,
      rate: toNumber3(body.broker_revenue_rate),
      amount: brokerRevenueAmount,
      status: body.broker_revenue_status ?? "expected"
    });
    if (error)
      return badRequest(error.message);
  }
  const repCommissionAmount = toNumber3(body.sales_rep_commission_amount);
  if (user.role === "admin" && repCommissionAmount !== null && repCommissionAmount >= 0 && merchantRow.assigned_rep_id) {
    const { error } = await supabaseAdmin.from("sales_rep_commissions").insert({
      funding_id: fundingRow.id,
      sales_rep_id: merchantRow.assigned_rep_id,
      basis_type: "broker_revenue",
      basis_amount: brokerRevenueAmount ?? fundedAmount,
      rate: toNumber3(body.sales_rep_commission_rate),
      amount: repCommissionAmount,
      status: body.sales_rep_commission_status ?? "unpaid"
    });
    if (error)
      return badRequest(error.message);
  }
  try {
    const renewal = await ensureRenewalForFunding({
      funding_id: fundingRow.id,
      merchant_id: body.merchant_id,
      funded_at: fundingRow.funded_at,
      assigned_rep_id: merchantRow.assigned_rep_id,
      created_by: user.id
    });
    if (renewal) {
      recordActivity({
        entity_type: "merchant",
        entity_id: body.merchant_id,
        user_id: user.id,
        activity_type: "system",
        body: `Renewal opportunity created; eligible on ${renewal.eligibility_date}`,
        metadata: { renewal_id: renewal.id, funding_id: fundingRow.id, eligibility_date: renewal.eligibility_date }
      });
    }
  } catch (err) {
    console.error("[fundings] Failed to create renewal opportunity:", err);
  }
  recordActivity({
    entity_type: "funding",
    entity_id: fundingRow.id,
    user_id: user.id,
    activity_type: "system",
    body: `Deal funded: ${fundingRow.merchant?.business_name ?? body.merchant_id} for $${fundedAmount.toLocaleString()}`,
    metadata: { merchant_id: body.merchant_id, lender_id: lenderId, funding_id: fundingRow.id, funded_amount: fundedAmount }
  });
  recordActivity({
    entity_type: "merchant",
    entity_id: body.merchant_id,
    user_id: user.id,
    activity_type: "system",
    body: `Deal funded for $${fundedAmount.toLocaleString()}`,
    metadata: { funding_id: fundingRow.id, lender_id: lenderId, funded_amount: fundedAmount }
  });
  triggerMerchantStatusEmail(body.merchant_id, FUNDED_STATUS);
  return json(toFunding(fundingRow), { status: 201 });
}

