async function GET23(req) {
  const user = await requireAuth(req);
  if (user.role === "merchant")
    return forbidden();
  const url = new URL(req.url);
  const merchantId = url.searchParams.get("merchant_id");
  if (!merchantId)
    return badRequest("merchant_id is required");
  let query = supabaseAdmin.from("merchant_file_submissions").select("*, merchant:merchants(business_name,assigned_rep_id), lender:lenders(company_name,contact_name,contact_email)").eq("merchant_id", merchantId).order("submitted_at", { ascending: false });
  if (user.role === "sales_rep") {
    const allowed = await salesRepCanAccessMerchant2(user.id, merchantId);
    if (allowed instanceof Response)
      return allowed;
    if (!allowed)
      return forbidden();
  }
  if (user.role === "lender") {
    const lenderId = await getCurrentLenderId3(user.id);
    if (lenderId instanceof Response)
      return lenderId;
    if (!lenderId)
      return forbidden();
    query = query.eq("lender_id", lenderId);
  }
  const { data, error } = await query.returns();
  if (error)
    return badRequest(error.message);
  return json((data ?? []).map(toMerchantFileSubmission));
}
async function POST23(req) {
  const user = await requireAuth(req);
  const roleError = assertRole(user, ["admin", "sales_rep"]);
  if (roleError)
    return roleError;
  const body = await req.json();
  if (!body.merchant_id || !body.lender_id)
    return badRequest("merchant_id and lender_id are required");
  if (body.status && !isSubmissionStatus(body.status))
    return badRequest("status is invalid");
  if (user.role === "sales_rep") {
    const allowed = await salesRepCanAccessMerchant2(user.id, body.merchant_id);
    if (allowed instanceof Response)
      return allowed;
    if (!allowed)
      return forbidden();
  }
  let matchId = body.match_id ?? null;
  if (!matchId) {
    const { data: match, error: matchError } = await supabaseAdmin.from("lender_matches").select("id").eq("merchant_id", body.merchant_id).eq("lender_id", body.lender_id).maybeSingle();
    if (matchError)
      return badRequest(matchError.message);
    matchId = match?.id ?? null;
  }
  try {
    const row = await upsertMerchantFileSubmission({
      merchant_id: body.merchant_id,
      lender_id: body.lender_id,
      match_id: matchId,
      submitted_by: user.id,
      submitted_at: new Date().toISOString(),
      status: body.status ?? "submitted",
      notes: body.notes ?? null
    });
    recordActivity({
      entity_type: "merchant",
      entity_id: body.merchant_id,
      user_id: user.id,
      activity_type: "match",
      body: `Merchant file submitted to ${row.lender?.company_name ?? "lender/funder"}`,
      metadata: { submission_id: row.id, lender_id: body.lender_id, status: row.status }
    });
    return json(toMerchantFileSubmission(row), { status: 201 });
  } catch (error) {
    return badRequest(error instanceof Error ? error.message : "Could not create merchant-file submission");
  }
}

// src/routes/merchant-file-submissions/[id].ts
async function fetchSubmission(id) {
  const { data, error } = await supabaseAdmin.from("merchant_file_submissions").select("*, merchant:merchants(business_name,assigned_rep_id), lender:lenders(company_name,contact_name,contact_email)").eq("id", id).maybeSingle();
  if (error)
    return badRequest(error.message);
  return data ?? null;
}
function canManageSubmission(userId, role, submission) {
  if (role === "admin")
    return true;
  if (role === "sales_rep")
    return submission.merchant?.assigned_rep_id === userId;
  return false;
}
async function PATCH11(req, context) {
  const user = await requireAuth(req);
  const roleError = assertRole(user, ["admin", "sales_rep"]);
  if (roleError)
    return roleError;
  const id = getId(context);
  if (!id)
    return badRequest();
  const submission = await fetchSubmission(id);
  if (submission instanceof Response)
    return submission;
  if (!submission)
    return notFound();
  if (!canManageSubmission(user.id, user.role, submission))
    return forbidden();
  const body = await req.json();
  if (body.status !== undefined && !isSubmissionStatus(body.status))
    return badRequest("status is invalid");
  const update = { updated_at: new Date().toISOString() };
  if (body.status !== undefined) {
    update.status = body.status;
    if (body.status === "declined" || body.status === "no_response" || body.status === "offer_received" || body.status === "stips_requested") {
      update.response_at = new Date().toISOString();
    }
  }
  if (body.decline_reason !== undefined)
    update.decline_reason = body.decline_reason?.trim() || null;
  if (body.notes !== undefined)
    update.notes = body.notes?.trim() || null;
  const { data, error } = await supabaseAdmin.from("merchant_file_submissions").update(update).eq("id", id).select("*, merchant:merchants(business_name,assigned_rep_id), lender:lenders(company_name,contact_name,contact_email)").single();
  if (error)
    return badRequest(error.message);
  const changedStatus = body.status && body.status !== submission.status;
  recordActivity({
    entity_type: "merchant",
    entity_id: data.merchant_id,
    user_id: user.id,
    activity_type: "match",
    body: changedStatus ? `Merchant-file submission to ${data.lender?.company_name ?? "lender/funder"} marked ${data.status}` : `Merchant-file submission updated for ${data.lender?.company_name ?? "lender/funder"}`,
    metadata: { submission_id: data.id, lender_id: data.lender_id, status: data.status, previous_status: submission.status }
  });
  return json(toMerchantFileSubmission(data));
}

// src/routes/search/index.ts
async function GET24(req) {
  const user = await requireAuth(req);
  if (user.role === "merchant" || user.role === "lender")
    return forbidden();
  const url = new URL(req.url);
  const searchTerm = cleanSearchTerm(url.searchParams.get("q"));
  if (!searchTerm)
    return json({ merchants: [], leads: [], lenders: [], query: "" });
  if (searchTerm.length > 100)
    return badRequest("Search term is too long");
  const q = `%${searchTerm}%`;
  let merchantsQuery = supabaseAdmin.from("merchants").select("id,business_name,status,state,assigned_rep_id").or(`business_name.ilike.${q},state.ilike.${q},industry.ilike.${q}`);
  let leadsQuery = supabaseAdmin.from("leads").select("id,business_name,owner_name,status,assigned_rep_id").or(`business_name.ilike.${q},owner_name.ilike.${q},email.ilike.${q}`);
  if (user.role === "sales_rep") {
    merchantsQuery = merchantsQuery.eq("assigned_rep_id", user.id);
    leadsQuery = leadsQuery.or(`assigned_rep_id.eq.${user.id},created_by.eq.${user.id}`);
  }
  const merchantsRequest = merchantsQuery.limit(10).returns();
  const leadsRequest = leadsQuery.limit(10).returns();
  const lendersQuery = supabaseAdmin.from("lenders").select("id,company_name,contact_name,contact_email").or(`company_name.ilike.${q},contact_name.ilike.${q},contact_email.ilike.${q}`).limit(10).returns();
  const [merchants, leads, lenders] = await Promise.all([merchantsRequest, leadsRequest, lendersQuery]);
  if (merchants.error)
    return badRequest(merchants.error.message);
  if (leads.error)
    return badRequest(leads.error.message);
  if (lenders.error)
    return badRequest(lenders.error.message);
  return json({
    merchants: merchants.data ?? [],
    leads: leads.data ?? [],
    lenders: lenders.data ?? [],
    query: searchTerm
  });
}

// src/routes/saved-views/index.ts
var ENTITY_TYPES2 = ["merchants", "leads", "lenders", "tasks", "fundings"];
var isSavedViewEntityType = (value) => typeof value === "string" && ENTITY_TYPES2.includes(value);
function toSavedView(row) {
  return {
    id: row.id,
    user_id: row.user_id,
    name: row.name,
    entity_type: row.entity_type,
    filters: row.filters ?? {},
    sort: row.sort ?? {},
    is_shared: Boolean(row.is_shared),
    created_at: row.created_at,
    updated_at: row.updated_at
  };
}
async function GET25(req) {
  const user = await requireAuth(req);
  const roleError = assertRole(user, ["admin", "sales_rep"]);
  if (roleError)
    return roleError;
  const url = new URL(req.url);
  const entityType = url.searchParams.get("entity_type");
  if (entityType && !isSavedViewEntityType(entityType))
    return badRequest("entity_type is invalid");
  let query = supabaseAdmin.from("saved_views").select("*").or(`user_id.eq.${user.id},is_shared.eq.true`).order("is_shared", { ascending: false }).order("name", { ascending: true });
  if (entityType)
    query = query.eq("entity_type", entityType);
  const { data, error } = await query.returns();
  if (error)
    return badRequest(error.message);
  return json((data ?? []).map(toSavedView));
}
async function POST24(req) {
  const user = await requireAuth(req);
  const roleError = assertRole(user, ["admin", "sales_rep"]);
  if (roleError)
    return roleError;
  const body = await req.json();
  if (!body.name?.trim())
    return badRequest("name is required");
  if (!isSavedViewEntityType(body.entity_type))
    return badRequest("entity_type is required");
  if (body.is_shared && user.role !== "admin")
    return forbidden("Only admins can create shared saved views");
  const { data, error } = await supabaseAdmin.from("saved_views").insert({
    user_id: user.id,
    name: body.name.trim(),
    entity_type: body.entity_type,
    filters: body.filters ?? {},
    sort: body.sort ?? {},
    is_shared: user.role === "admin" ? Boolean(body.is_shared) : false
  }).select("*").single();
  if (error)
    return badRequest(error.message);
  return json(toSavedView(data), { status: 201 });
}

// src/routes/saved-views/[id].ts
async function getSavedView(id) {
  const { data, error } = await supabaseAdmin.from("saved_views").select("*").eq("id", id).maybeSingle();
  if (error)
    return badRequest(error.message);
  if (!data)
    return notFound("Saved view not found");
  return data;
}
function canModify(user, view) {
  return user.role === "admin" || view.user_id === user.id;
}
async function PATCH12(req, context) {
  const user = await requireAuth(req);
  const roleError = assertRole(user, ["admin", "sales_rep"]);
  if (roleError)
    return roleError;
  const id = getId(context);
  if (!id)
    return badRequest("id is required");
  const existing = await getSavedView(id);
  if (existing instanceof Response)
    return existing;
  if (!canModify(user, existing))
    return forbidden();
  const body = await req.json();
  if (body.entity_type && !isSavedViewEntityType(body.entity_type))
    return badRequest("entity_type is invalid");
  if (body.is_shared && user.role !== "admin")
    return forbidden("Only admins can create shared saved views");
  const update = { updated_at: new Date().toISOString() };
  if (body.name !== undefined) {
    if (!body.name.trim())
      return badRequest("name cannot be blank");
    update.name = body.name.trim();
  }
  if (body.entity_type !== undefined)
    update.entity_type = body.entity_type;
  if (body.filters !== undefined)
    update.filters = body.filters;
  if (body.sort !== undefined)
    update.sort = body.sort;
  if (body.is_shared !== undefined)
    update.is_shared = user.role === "admin" ? Boolean(body.is_shared) : false;
  const { data, error } = await supabaseAdmin.from("saved_views").update(update).eq("id", id).select("*").single();
  if (error)
    return badRequest(error.message);
  return json(toSavedView(data));
}
async function DELETE7(_req, context) {
  const user = await requireAuth(_req);
  const roleError = assertRole(user, ["admin", "sales_rep"]);
  if (roleError)
    return roleError;
  const id = getId(context);
  if (!id)
    return badRequest("id is required");
  const existing = await getSavedView(id);
  if (existing instanceof Response)
    return existing;
  if (!canModify(user, existing))
    return forbidden();
  const { error } = await supabaseAdmin.from("saved_views").delete().eq("id", id);
  if (error)
    return badRequest(error.message);
  return json({ success: true });
}

